"use client";
import { useEffect, useState } from "react";
import axios from "axios";
import { useAuth } from "../../store/auth";
import { useRouter } from "next/navigation";

export default function Dashboard() {
  const { user, token } = useAuth();
  const router = useRouter();
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({
    name: "",
    price: "",
    description: "",
    image: "",
  });

  useEffect(() => {
    if (!token) router.push("/login");
    else if (user && !user.is_staff) router.push("/");
    else {
      axios
        .get("http://127.0.0.1:8000/api/products/", {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((res) => setProducts(res.data));
    }
  }, [token, user]);

  const addProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    await axios.post("http://127.0.0.1:8000/api/products/", form, {
      headers: { Authorization: `Bearer ${token}` },
    });
    setForm({ name: "", price: "", description: "", image: "" });
    window.location.reload();
  };

  if (!user?.is_staff) return null;

  return (
    <div className="max-w-7xl mx-auto px-6 py-16">
      <h1 className="text-5xl font-bold text-[var(--wave-blue)] mb-10">
        Admin Dashboard
      </h1>
      <form
        onSubmit={addProduct}
        className="bg-white p-8 rounded-xl shadow-lg mb-10"
      >
        <input
          placeholder="Name"
          required
          className="w-full p-4 border mb-4 rounded"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
        />
        <input
          placeholder="Price"
          type="number"
          step="0.01"
          required
          className="w-full p-4 border mb-4 rounded"
          value={form.price}
          onChange={(e) => setForm({ ...form, price: e.target.value })}
        />
        <textarea
          placeholder="Description"
          className="w-full p-4 border mb-4 rounded"
          value={form.description}
          onChange={(e) => setForm({ ...form, description: e.target.value })}
        />
        <input
          placeholder="Image URL (optional)"
          className="w-full p-4 border mb-4 rounded"
          value={form.image}
          onChange={(e) => setForm({ ...form, image: e.target.value })}
        />
        <button className="bg-[var(--wave-blue)] text-white px-8 py-4 rounded-lg text-xl">
          Add Product
        </button>
      </form>

      <div className="grid grid-cols-3 gap-8">
        {products.map((p: any) => (
          <div key={p.id} className="bg-white p-6 rounded-xl shadow">
            <h3 className="font-bold text-xl">{p.name}</h3>
            <p className="text-2xl text-[var(--wave-blue)]">${p.price}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
